 ],
 "bounds": [
  {
   "id": "B1",
   "layer": "org-policy",
   "owner": "controller",
   "parameter": "refundApprovalThresholdMinor",
   "min": 0,
   "max": 100000,
   "statement": "Group policy: no refund above EUR 1,000.00 leaves any entity without an approval. An entity rule may set a lower threshold, never a higher one."
  }
 ],
 "parameters": {
  "refundApprovalThresholdMinor": 50000,
  "currency": "EUR"
 },
 "clauses": [
  {
   "id": "C1",
   "title": "Conservation and exactly-once money movement",
   "layer": "org-policy",
   "owner": {
    "role": "controller",
    "principal": "u-ctl1"
   },
   "assurance": [
    "monitorable"
   ],
   "statement": "Per order and fulfilment: the amount captured less the amount refunded equals what the customer owes for what the workflow delivered (zero for a fulfilment it set failed or cancelled; the charge for one it set completed); a refund never exceeds the captures it returns; a fulfilment is charged at most once, with one idempotency key per logical charge, for the amount of the edition in force at placement.",
   "check": {
    "kind": "conservation",
    "objects": [
     "order",
     "fulfilment",
     "payment"
    ]
   },
   "narrows": [],
   "exceptions": [],
   "evidence": [
    {
     "id": "C1-E1",
     "what": "every committed charge and refund attempt with key, fulfilment and amount",
     "source": "host journal: ledger rows joined to effect.emit"
    },
    {
     "id": "C1-E2",
     "what": "each fulfilment's outcome as the workflow set it",
     "source": "host journal: orders.setStatus ledger rows"
    }
   ]
  },
  {
   "id": "C2",
   "title": "Refund authority with separation of duties",
   "layer": "entity-rule",
   "owner": {
    "role": "finance",
    "principal": "u-fin1"
   },
   "assurance": [
    "provable",
    "monitorable"
   ],
   "statement": "A refund whose amount is above T (parameter refundApprovalThresholdMinor of the version pinned for the order) is applied only after a principal holding finance-approver approves it in a refundApproval task whose subject is the fulfilment and whose question states the amount; the approver must not be a principal who entered an amend or a cancel of the order.",
   "check": {
    "kind": "approval-above-threshold",
    "effect": "billing.refund",
    "amountArg": "amountMinor",
    "parameter": "refundApprovalThresholdMinor",
    "approverRole": "finance-approver",
    "taskKind": "refundApproval",
    "taskSubject": "fulfilmentId",
    "sodExclude": [
     "entered-amend",
     "entered-cancel"
    ]
   },
   "narrows": [
    "B1"
   ],
   "exceptions": [
    {
     "id": "C2-X1",
     "kind": "break-glass",
     "who": "controller",
     "when": "no valid finance approval after three requests for the same refund",
     "requires": [
      "justification",
      "after-the-fact-review",
      "journal"
     ],
     "reviewBy": "finance",
     "reviewWithinHours": 72
    }
   ],
   "evidence": [
    {
     "id": "C2-E1",
     "what": "the approval task, bound to the fulfilment (subject) and the refund amount",
     "source": "host journal: humanTask.created"
    },
    {
     "id": "C2-E2",
     "what": "the answer and the approving principal",
     "source": "host journal: humanTask.answered delivery"
    },
    {
     "id": "C2-E3",
     "what": "the approver's roles under the pinned version",
     "source": "constitution registry journal"
    },
    {
     "id": "C2-E4",
     "what": "the principals who entered an amend or cancel of the order",
     "source": "host journal: customer.action deliveries (enteredBy)"
    },
    {
     "id": "C2-E5",
     "what": "the hold and release of the refund, with clause id and constitution hash",
     "source": "host journal: port decisions in call rows"
    }
   ]
  },
  {
   "id": "C3",
   "title": "Change control and pinning",
   "layer": "org-policy",
   "owner": {
    "role": "controller",
    "principal": "u-ctl1"
   },
   "assurance": [
    "provable"
   ],
   "statement": "The constitution changes only by a new version proposed by a holder of finance or controller and approved, before its effectiveFrom, by a holder of controller under the version in force who is not the proposer; every parameter stays within the bounds of higher layers. Every run is pinned to the hash of the version in force at its order's placement and journals that hash with every governed decision.",
   "check": {
    "kind": "change-control",
    "proposerRoles": [
     "finance",
     "controller"
    ],
    "approverRole": "controller",
    "sodExclude": [
     "proposer"
    ],
    "approvalBeforeEffective": true,
    "pinAt": "order.placedAt"
   },
   "narrows": [],
   "exceptions": [
    {
     "id": "C3-X1",
     "kind": "emergency-change",
     "who": "controller",
     "when": "a change that cannot wait for a second principal (declared, not exercised in OT-0)",
     "requires": [
      "justification",
      "after-the-fact-review",
      "journal"
     ],
     "reviewBy": "finance",
     "reviewWithinHours": 72
    }
   ],
   "evidence": [
    {
     "id": "C3-E1",
     "what": "every version with proposer, approvals and the gate decision (in force, refused, reasons)",
     "source": "constitution registry journal (hash-chained)"
    },
    {
     "id": "C3-E2",
     "what": "the constitution hash pinned for each run",
     "source": "host journal: decisions.constitution.pins in call rows"
    }
   ]
  }
 ],
 "change": {
  "proposerRoles": [
   "finance",
   "controller"
  ],
  "approverRole": "controller",
  "proposerMayApprove": false,
  "approvalBeforeEffective": true
 }
}
