}

function finish(X) {
  const { S, out } = X;
  if (S.o) {
    out.decisions.subject = S.o;
    out.decisions.constitution = { pins: { [S.o]: S.pin?.hash || '' } };
  }
  const inFlight = Object.values(S.st).some((st) => st.state === 'issued' || st.state === 'unknown');
  if (S.ended && !inFlight) out.close = true;
  out.carry = S;
  return out;
}

