    if (effFrom !== undefined && ms(a.at) >= effFrom) return false;
    const base = under || v;
    const pr = (base.principals || []).find((x) => x.id === a.by);
    const rs = pr ? pr.roles || [] : [];
    const proposal = logEntry.find((e) => e.type === 'proposed' && e.version === v.version);
