}

function applyVerdict(X) {
  const { S } = X;
  if (S.stopped) return;
  if (S.verdict === 'reject') stop(X, X.now, 'fraud');
  else if (S.verdict === 'pass') clearAt(X, S.p);
  else {
    S.fraud = 'review';
    S.rv = { deadline: X.now + S.fraudH * HOUR, n: 0, open: null };
    askReview(X);
